code.java:
class Solution {
    public List<Integer> findWordsContaining(String[] words,char x){
        List<Integer> answer=new ArrayList<>();
        for(int index=0;index<words.length;index++)if(words[index].indexOf(x)>=0)answer.add(index);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun findWordsContaining(words:Array<String>,x:Char):List<Int>{
        val answer=mutableListOf<Int>();
        for(index in words.indices)if(x in words[index])answer.add(index);
        return answer
    }
}

code.cpp:
class Solution {
    public:vector<int> findWordsContaining(vector<string>& words,char x){
        vector<int> answer;
        for(int index=0;index<(int)words.size();++index)if(words[index].find(x)!=string::npos)answer.push_back(index);
        return answer;
    }
};
